//! Runtime COMBINE boundary.
use crate::combine::{bond_strength, eligible_candidates};
use crate::contact::ConnectionCompatibilityCache;
use crate::resources::{BaseResource, ConnectionSites, Material};
use crate::state::{Environment, Organism};
use crate::structure::{Placement, StructuralUnit};
const EPSILON:f64=1e-12;const COMBINE_CONTACT_TOLERANCE:f64=1.0;
#[derive(Clone,Copy,Debug,PartialEq)]pub(crate)struct CombineAttempt{pub unit_a:usize,pub unit_b:usize,pub point_a:usize,pub point_b:usize,pub work_cost:f64,pub energy_paid:f64,pub interaction_direction:f64,pub interaction_magnitude:f64,pub formation_threshold:f64,pub surplus:f64,pub bond_strength:f64,pub bond_energy:f64}
pub(crate)fn instantiate_one_unit(organism:&mut Organism,catalog:&[BaseResource])->Option<usize>{let material=organism.stored_material.peek_one_unstructured()?;let resource_name=material.parts.first().filter(|(_,a)|(*a-1.0).abs()<=EPSILON).map(|(n,_)|n.clone())?;if material.parts.len()!=1||catalog.iter().all(|b|b.name!=resource_name){return None}let material=organism.stored_material.take_one_unstructured_named(&resource_name)?;let(x,y)=organism.occupied_cells.first().map(|p|(p.x,p.y)).unwrap_or((0.0,0.0));debug_assert_eq!(material.total_amount(),1.0);Some(organism.structure.add_unit(StructuralUnit::from_material(material,Placement{x,y,rotation_radians:0.0})?))}
fn water_field_amount(environment:&Environment,organism:&Organism)->f64{organism.occupied_cells.first().and_then(|p|environment.field.index_for_position(p.x,p.y)).map(|i|environment.field.cells[i].materials.iter().flat_map(|m|m.parts.iter()).filter(|(n,_)|n=="Water").map(|(_,a)|*a).sum()).unwrap_or(0.0)}
fn placement_for_connection(existing:&crate::structure::StructuralUnit,existing_point:crate::resources::ConnectionPoint,new_point:crate::resources::ConnectionPoint)->Placement{let w=crate::contact::world_connection_point(existing_point,existing);let angle=w.normal_y.atan2(w.normal_x);let rotation=angle+std::f64::consts::PI-new_point.direction_radians;let(s,c)=rotation.sin_cos();let rx=new_point.x*c-new_point.y*s;let ry=new_point.x*s+new_point.y*c;Placement{x:w.x-rx,y:w.y-ry,rotation_radians:rotation}}
pub(crate)fn try_combine_stored_unit(organism:&mut Organism,environment:&Environment,cache:&mut ConnectionCompatibilityCache)->Option<CombineAttempt>{let raw=organism.stored_material.peek_one_unstructured()?;if raw.parts.len()!=1||!raw.internal_bonds.is_empty()||(raw.parts[0].1-1.0).abs()>EPSILON||environment.catalog.iter().all(|b|b.name!=raw.parts[0].0){return None}let resource_name=raw.parts[0].0.clone();let new_sites=match environment.catalog.iter().find(|b|b.name==resource_name).map(|b|b.shape.connection_sites()){Some(ConnectionSites::Corners(p))=>p,_=>return None};let mut best=None;let water=water_field_amount(environment,organism);for ua in 0..organism.structure.units.len(){let Some(ConnectionSites::Corners(existing))=organism.structure.units[ua].connection_sites(&environment.catalog)else{continue};for(pa,&ep)in existing.iter().enumerate(){if organism.structure.connection_count(ua,pa)!=0{continue}for &np in &new_sites{let placement=placement_for_connection(&organism.structure.units[ua],ep,np);let mut hypothetical=organism.structure.clone();let ub=hypothetical.add_unit(StructuralUnit::from_material(raw.clone(),placement)?);for candidate in crate::contact::connection_pair_candidates_cached(&hypothetical,ua,ub,&environment.catalog,cache).into_iter().filter(|c|c.point_a==pa&&c.distance<=COMBINE_CONTACT_TOLERANCE&&c.available_a&&c.available_b){let a=hypothetical.units[ua].properties(&environment.catalog)?;let b=hypothetical.units[ub].properties(&environment.catalog)?;let evaluation=crate::combine::evaluate_formation(candidate,a.cohesion,b.cohesion);let(interaction,work,paid)=crate::structural_combine::required_investment(a,b,evaluation,water).ok()?;if best.as_ref().map(|x|paid<x.6).unwrap_or(true){best=Some((ua,pa,placement,evaluation,interaction,work,paid));}}}}}let(ua,pa,placement,evaluation,interaction,work,paid)=best?;if organism.usable_energy+EPSILON<paid{return None}let props_a=organism.structure.units[ua].properties(&environment.catalog)?;let props_b=environment.catalog.iter().find(|b|b.name==resource_name).map(|b|b.properties)?;let bs=bond_strength(props_a,props_b);let material=organism.stored_material.take_one_unstructured_named(&resource_name)?;let ub=match StructuralUnit::from_material(material.clone(),placement){Some(u)=>organism.structure.add_unit(u),None=>{debug_assert!(organism.store_material(material));return None}};let bond=crate::structure::Bond{unit_a:ua,point_a:pa,unit_b:ub,point_b:evaluation.candidate.point_b,strength:bs,bond_energy:(paid-evaluation.threshold).max(0.0)};let bond_index=match crate::contact::try_add_bond(&mut organism.structure,bond,&environment.catalog){Ok(i)=>i,Err(_)=>{organism.structure.units.pop();debug_assert!(organism.store_material(material));return None}};debug_assert_eq!(bond_index,organism.structure.bonds.len()-1);organism.usable_energy-=paid;Some(CombineAttempt{unit_a:ua,unit_b:ub,point_a:pa,point_b:evaluation.candidate.point_b,work_cost:work,energy_paid:paid,interaction_direction:interaction.direction,interaction_magnitude:interaction.magnitude,formation_threshold:evaluation.threshold,surplus:paid-evaluation.threshold,bond_strength:bs,bond_energy:(paid-evaluation.threshold).max(0.0)})}
pub(crate)fn try_combine(organism:&mut Organism,environment:&Environment,cache:&mut ConnectionCompatibilityCache)->Option<CombineAttempt>{if organism.structure.units.len()>=1&&!organism.stored_material.is_empty(){if let Some(a)=try_combine_stored_unit(organism,environment,cache){return Some(a)}}if organism.structure.units.len()<2{return None}let catalog=&environment.catalog;let mut best=None;for ua in 0..organism.structure.units.len(){for ub in ua+1..organism.structure.units.len(){for e in eligible_candidates(&organism.structure,ua,ub,catalog,cache).into_iter().filter(|c|c.distance<=COMBINE_CONTACT_TOLERANCE).filter_map(|c|{let a=organism.structure.units[ua].properties(catalog)?;let b=organism.structure.units[ub].properties(catalog)?;Some(crate::combine::evaluate_formation(c,a.cohesion,b.cohesion))}){if best.as_ref().map(|(_,_,x)|e.candidate.distance<x.candidate.distance).unwrap_or(true){best=Some((ua,ub,e))}}}}let(ua,ub,e)=best?;let a=organism.structure.units[ua].properties(catalog)?;let b=organism.structure.units[ub].properties(catalog)?;let(interaction,work,paid)=crate::structural_combine::required_investment(a,b,e,water_field_amount(environment,organism)).ok()?;if organism.usable_energy+EPSILON<paid{return None}let bs=bond_strength(a,b);let be=paid-e.threshold;crate::contact::try_add_bond(&mut organism.structure,crate::structure::Bond{unit_a:ua,point_a:e.candidate.point_a,unit_b:ub,point_b:e.candidate.point_b,strength:bs,bond_energy:be},catalog).ok()?;organism.usable_energy-=paid;Some(CombineAttempt{unit_a:ua,unit_b:ub,point_a:e.candidate.point_a,point_b:e.candidate.point_b,work_cost:work,energy_paid:paid,interaction_direction:interaction.direction,interaction_magnitude:interaction.magnitude,formation_threshold:e.threshold,surplus:be,bond_strength:bs,bond_energy:be})}
#[allow(dead_code)]fn _raw_material_type_check(raw:&Material,catalog:&[BaseResource])->bool{!raw.has_internal_structure()&&raw.parts.iter().all(|(n,a)|*a>=0.0&&catalog.iter().any(|r|r.name==*n))}
